            for edge in explicit:
                live = registry.threads.get(edge.peer)
                visible[(edge.peer, edge.peer_created)] = RelationshipEntry(
                    edge.peer,
                    "thread",
                    detail=edge.note,
                    available=live is not None and live.created_at == edge.peer_created,
                    sources=("explicit",),
